package br.com.confirmacao.admin.application;
import br.com.confirmacao.patient.application.*;import br.com.confirmacao.patient.domain.*;import br.com.confirmacao.patient.infrastructure.PatientRepository;import br.com.confirmacao.session.domain.SessionStatus;import br.com.confirmacao.session.infrastructure.SessionAppointmentRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class AdminPatientService{private final PatientRepository patients;private final SessionAppointmentRepository sessions;public AdminPatientService(PatientRepository p,SessionAppointmentRepository s){patients=p;sessions=s;}@Transactional public Patient update(UUID id,String name,LocalDate birth,String phone,String email,PreferredContactChannel channel,Boolean reminders){Patient patient=find(id);UUID professionalId=patient.getProfessional().getId();String normalized=phone==null?null:phone.replaceAll("\\D","");if(patients.existsByProfessionalIdAndPhoneAndIdNot(professionalId,normalized,id))throw new PatientAlreadyExistsException();patient.update(name,birth,phone,email,channel);patient.setWhatsappRemindersEnabled(reminders,"ADMIN");return patient;}@Transactional public void activate(UUID id){find(id).activate();}@Transactional public void deactivate(UUID id){var patient=find(id);if(sessions.existsByProfessionalIdAndPatientIdAndStatusInAndEndsAtAfter(patient.getProfessional().getId(),id,List.of(SessionStatus.SCHEDULED,SessionStatus.CONFIRMED),Instant.now()))throw new IllegalArgumentException("Cancele ou reagende as sessões futuras antes de desativar o paciente");patient.deactivate();}private Patient find(UUID id){return patients.findById(id).orElseThrow(()->new PatientNotFoundException(id));}}
